const { MongoClient } = require('mongodb');
const fs = require('fs');
const path = require('path');

const MONGO_URI = process.env.MONGODB_URI || 'mongodb://127.0.0.1:27017/tourtovalencia';
const OUTPUT_DIR = path.join(__dirname, '../public/locales');

async function migrateTranslations() {
  const client = new MongoClient(MONGO_URI);

  try {
    await client.connect();
    const db = client.db('tourtovalencia');

    console.log('Extrayendo traducciones de tours...');
    const tours = await db.collection('tours').find({}).toArray();

    const toursTranslations = {
      es: {},
      en: {}
    };

    for (const tour of tours) {
      const slug = tour.slug || tour._id.toString();

      const translationFields = ['tourName', 'description', 'duration', 'includes', 'meetingPoint'];

      for (const field of translationFields) {
        if (tour[field]) {
          if (tour[field].es) {
            toursTranslations.es[`tours.${slug}.${field}`] = tour[field].es;
          }
          if (tour[field].en) {
            toursTranslations.en[`tours.${slug}.${field}`] = tour[field].en;
          }
        }
      }
    }

    console.log('Extrayendo traducciones de páginas...');
    const pages = await db.collection('pages').find({}).toArray();

    const pagesTranslations = {
      es: {},
      en: {}
    };

    for (const page of pages) {
      const slug = page.slug;

      if (page.content) {
        ['es', 'en'].forEach(lang => {
          if (page.content[lang]) {
            const content = page.content[lang];
            pagesTranslations[lang][`pages.${slug}.content`] = JSON.stringify(content);
          }
        });
      }
    }

    const localesDir = path.join(OUTPUT_DIR);

    fs.writeFileSync(
      path.join(localesDir, 'es/tours.json'),
      JSON.stringify(toursTranslations.es, null, 2)
    );
    fs.writeFileSync(
      path.join(localesDir, 'en/tours.json'),
      JSON.stringify(toursTranslations.en, null, 2)
    );

    fs.writeFileSync(
      path.join(localesDir, 'es/pages-content.json'),
      JSON.stringify(pagesTranslations.es, null, 2)
    );
    fs.writeFileSync(
      path.join(localesDir, 'en/pages-content.json'),
      JSON.stringify(pagesTranslations.en, null, 2)
    );

    console.log('Traducciones exportadas a:', OUTPUT_DIR);
    console.log('Archivos creados:');
    console.log('  - es/tours.json');
    console.log('  - en/tours.json');
    console.log('  - es/pages-content.json');
    console.log('  - en/pages-content.json');

  } finally {
    await client.close();
  }
}

migrateTranslations().catch(console.error);
